let counter = 0
setTimeout(() => console.log('timer sees', counter), 0)
for (let i = 0; i < 1_000_000; i++) counter++
console.log('loop done', counter)
// loop done 1000000
// timer sees 1000000   (the timer could not cut into the loop)

let spins = 0
setTimeout(() => console.log('timer ran after', spins, 'spins'), 0)
function spin(): void {
  if (++spins < 100_000) queueMicrotask(spin)  // each microtask queues another
}
spin()
// timer ran after 100000 spins: without the cap it would never run

// Blocking: one task holds the thread until every item is done
function sumAll(xs: number[]): number {
  let s = 0
  for (const x of xs) s += x
  return s
}

// Chunked: each slice runs in its own task; timers and events run in between
async function sumChunked(xs: number[], size = 10_000): Promise<number> {
  let s = 0
  for (let i = 0; i < xs.length; i += size) {
    for (let j = i; j < Math.min(i + size, xs.length); j++) s += xs[j]
    await new Promise<void>(resolve => setTimeout(resolve, 0))
  }
  return s
}

