const yieldToLoop = (): Promise<void> => new Promise(resolve => setTimeout(resolve, 0))

async function countWords(lines: string[], linesPerChunk = 500): Promise<number> {
  let words = 0
  for (let i = 0; i < lines.length; i++) {
    words += lines[i].split(/\s+/).filter(Boolean).length
    if ((i + 1) % linesPerChunk === 0) await yieldToLoop()  // let timers and events in
  }
  return words
}

countWords(['the event loop', '', 'runs one task at a time']).then(n => console.log(n))  // 9

