  done = true
  return log
}

solution:
async function chunkedSums(nums: number[], size: number): Promise<string[]> {
  const log: string[] = []
  let done = false
  const heartbeat = (): void => {
    if (done) return
    log.push('tick')
    setTimeout(heartbeat, 0)
  }
  setTimeout(heartbeat, 0)
  for (let start = 0; start < nums.length; start += size) {
    if (start > 0) await new Promise<void>(resolve => setTimeout(resolve, 0))
    let sum = 0
    for (const n of nums.slice(start, start + size)) sum += n
    log.push(`sum ${sum}`)
  }
  done = true
  return log
}

The only change from the starter is **how** the loop yields. A resolved-promise `await` resumes in the microtask queue, which the event loop drains before it serves any timer, so all chunks would run back to back in one turn. Awaiting a `setTimeout` puts the continuation behind the heartbeat timer in the FIFO task queue: heartbeat, chunk, heartbeat, chunk. The first chunk runs synchronously in the call, there is no yield after the last chunk, and the pending heartbeat that fires after the work sees `done` and stops, so the log never ends with a stray tick. Each case costs O(n) work plus one task per chunk.

