type Kind = 'sync' | 'micro' | 'macro'

function scheduleAll(jobs: [string, Kind][]): Promise<string[]> {
  const log: string[] = []
  for (const [label, kind] of jobs) {
    if (kind === 'sync') log.push(label)
    else if (kind === 'micro') queueMicrotask(() => log.push(label))
    else setTimeout(() => log.push(label), 0)
  }
  return new Promise(resolve => setTimeout(() => resolve(log), 0))
}

async function batchedFlushes(ops: string[]): Promise<string[][]> {
  const flushes: string[][] = []
  let pending: string[] = []
  let scheduled = false
  const flush = (): void => {
    scheduled = false
    flushes.push([...new Set(pending)])
    pending = []
  }
  const set = (value: string): void => {
    pending.push(value)
    if (!scheduled) {
      scheduled = true
      queueMicrotask(flush)
    }
  }
  for (const op of ops) {
    if (op === '|') await new Promise<void>(resolve => setTimeout(resolve, 0))
    else set(op)
  }
  await Promise.resolve()
  return flushes
}

